python3 - <<'PYEOF'
import xml.etree.ElementTree as ET
import sys

f = "/work/output/artifacts/skill-bpmn-subprocess/SubflowDemo.bpmn"
try:
    tree = ET.parse(f)
    root = tree.getroot()
    print("XML well-formed: OK")
except ET.ParseError as e:
    print(f"XML parse ERROR: {e}")
    sys.exit(1)

BN = "http://www.omg.org/spec/BPMN/20100524/MODEL"
DI = "http://www.omg.org/spec/BPMN/20100524/DI"

# Collect all declared ids
all_ids = {el.get("id") for el in root.iter() if el.get("id")}
print(f"All ids ({len(all_ids)}): {sorted(all_ids)}")

# Check refs resolve
import re
ref_attrs = ["sourceRef","targetRef","attachedToRef","bpmnElement","default","errorRef","messageRef","signalRef","calledElement"]
errors = []
for el in root.iter():
    for attr in ref_attrs:
        v = el.get(attr)
        if v and v not in all_ids:
            errors.append(f"UNRESOLVED {attr}={v!r} on <{el.tag}>")

if errors:
    for e in errors: print("ERROR:", e)
else:
    print("All refs resolve: OK")

# Check BPMNShape per visible node
plane = root.find(f".//{{{DI}}}BPMNPlane")
shapes = {s.get("bpmnElement") for s in plane.findall(f"{{{DI}}}BPMNShape")} if plane is not None else set()
edges  = {e.get("bpmnElement") for e in plane.findall(f"{{{DI}}}BPMNEdge")} if plane is not None else set()

# Collect flow nodes (not sequenceFlow)
flow_node_tags = {f"{{{BN}}}{t}" for t in
    ["startEvent","endEvent","task","scriptTask","userTask","serviceTask",
     "receiveTask","sendTask","subProcess","callActivity","exclusiveGateway",
     "parallelGateway","inclusiveGateway","eventBasedGateway","intermediateThrowEvent","intermediateCatchEvent","boundaryEvent"]}
flow_nodes = [el for el in root.iter() if el.tag in flow_node_tags]
node_ids = {n.get("id") for n in flow_nodes}
seq_flows = [el for el in root.iter() if el.tag == f"{{{BN}}}sequenceFlow"]
flow_ids  = {sf.get("id") for sf in seq_flows}

missing_shapes = node_ids - shapes
missing_edges  = flow_ids  - edges
if missing_shapes: print("MISSING shapes for:", missing_shapes)
else: print("All nodes have BPMNShape: OK")
if missing_edges:  print("MISSING edges for:", missing_edges)
else: print("All sequence flows have BPMNEdge: OK")

# Check subprocess has both inner start and end
sub = root.find(f".//{{{BN}}}subProcess")
if sub is not None:
    inner_starts = sub.findall(f"{{{BN}}}startEvent")
    inner_ends   = sub.findall(f"{{{BN}}}endEvent")
    print(f"SubProcess inner starts: {len(inner_starts)}, inner ends: {len(inner_ends)}")
    if len(inner_starts) != 1: print("ERROR: SubProcess must have exactly one start event")
    else: print("SubProcess start event count: OK")
else:
    print("No subProcess found")

print("Structural check complete.")
PYEOF
